        if not domain:
            return "Invalid URL format", 400

        # Simple check to ensure domain contains at least one dot (basic heuristic)
        # and doesn't look like a local address
        if '.' not in domain or domain.startswith('localhost'):
            return "Invalid domain", 400

    except Exception:
        return "Invalid URL format", 400

    return redirect(target_url)

